<template>
  <div class="ky-page" v-loading="loading"><div class="ky-page-header"><h2 class="ky-page-title">老人个体健康阈值</h2><el-select v-model="profileId" placeholder="选择健康档案" style="width:230px"><el-option v-for="p in profiles" :key="p.profile_id" :label="p.name" :value="p.profile_id" /></el-select><el-button :disabled="!profileId" @click="loadRules">刷新阈值</el-button></div>
    <el-alert v-if="error" type="error" :closable="false" :title="error" style="margin-bottom:16px" /><el-alert type="info" :closable="false" title="已审核的个体设置优先使用，未单独设置则继承院内默认。变更只影响之后录入，历史检测保留当时的阈值和结果。" style="margin-bottom:16px" />
    <div class="ky-card"><el-table :data="data.rules || []"><el-table-column prop="indicator_name" label="指标" min-width="120" /><el-table-column prop="unit" label="单位" /><el-table-column prop="level0_range" label="正常范围" min-width="130" /><el-table-column prop="level1_range" label="轻度" /><el-table-column prop="level2_range" label="较高" /><el-table-column prop="level3_range" label="高风险" min-width="130" /><el-table-column label="生效来源" min-width="120"><template #default="{row}"><el-tag :type="row.source==='PERSONAL'?'success':'info'">{{ row.source==='PERSONAL'?'个体设置':'院内默认' }}</el-tag><div class="ky-sub">版本 {{ row.version_id ?? '默认' }}</div></template></el-table-column><el-table-column v-if="canPropose" label="操作" width="150"><template #default="{row}"><el-button link type="primary" @click="open(row,false)">申请调整</el-button><el-button v-if="row.source==='PERSONAL'" link @click="open(row,true)">恢复默认</el-button></template></el-table-column></el-table><el-empty v-if="!data.rules?.length" description="暂无可展示的阈值，请选择档案或联系管理员配置" /></div>
    <div class="ky-card"><h3 class="ky-card__title">待审核申请</h3><el-table :data="data.pending || []"><el-table-column prop="indicator_name" label="指标" /><el-table-column prop="reason" label="申请依据" min-width="200" /><el-table-column label="申请时间"><template #default="{row}">{{ fmtDate(row.created_at || row.create_time) }}</template></el-table-column><el-table-column label="状态"><template #default>等待管理员审核，当前设置继续生效</template></el-table-column></el-table><el-empty v-if="!data.pending?.length" description="暂无待审核申请" /></div>
    <div class="ky-card"><h3 class="ky-card__title">阈值变更记录</h3><el-table :data="data.history || []"><el-table-column label="版本"><template #default="{row}">{{ row.version_id || row.id }}</template></el-table-column><el-table-column prop="indicator_name" label="指标" /><el-table-column label="状态"><template #default="{row}">{{ statusLabel(row.status) }}</template></el-table-column><el-table-column prop="reason" label="依据" min-width="180" /><el-table-column label="审核记录" min-width="180"><template #default="{row}">{{ row.review_note || row.note || '—' }}<div class="ky-sub">{{ fmtDate(row.reviewed_at || row.updated_at || row.created_at) }}</div></template></el-table-column></el-table><el-empty v-if="!data.history?.length" description="暂无变更记录" /></div>
    <el-dialog v-model="dialog" :title="restore?'申请恢复院内默认':'申请个体阈值调整'" width="min(620px,95vw)"><p>{{ form.indicator_name }} · 此申请经审核后生效</p><el-form label-position="top"><template v-if="!restore"><el-form-item v-for="n in [0,1,2,3]" :key="n" :label="n===0?'正常范围':'风险 '+n+' 级范围'"><el-input v-model="form['level'+n+'_range']" placeholder="如 90~139、>=180，多个范围用逗号分隔" /></el-form-item></template><el-form-item label="调整依据 / 医护确认记录"><el-input v-model="form.reason" type="textarea" :rows="3" maxlength="500" show-word-limit placeholder="记录实际依据，不能由 AI 自动设置或替代医护判断" /></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="submit">提交审核申请</el-button></template></el-dialog>
    
  </div>
</template>
<script setup>
import { ref,onMounted,watch,onBeforeUnmount } from 'vue'
import { useRoute } from 'vue-router'
import { ElMessage } from 'element-plus'
import { getUser } from '@/utils/auth'
import { fmtDate } from '@/utils/format'
import { listProfiles,getPersonalThresholds,proposePersonalThreshold } from '@/api'
const route=useRoute(),canPropose=['CARE','ADMIN'].includes(getUser()?.role),profiles=ref([]),profileId=ref(null),data=ref({}),loading=ref(false),saving=ref(false),error=ref(''),dialog=ref(false),restore=ref(false),form=ref({})
const formProfileId=ref(null)
let viewVersion=0,loadVersion=0
function profileChanged(){viewVersion++;data.value={};dialog.value=false;form.value={};error.value='';loadRules()}
watch(profileId,profileChanged,{flush:'sync'})
onBeforeUnmount(()=>{viewVersion++;loadVersion++})
function statusLabel(v){return ({PENDING:'待审核',APPROVED:'已通过',REJECTED:'已驳回',ACTIVE:'已生效',SUPERSEDED:'历史版本'})[v] || v}
async function loadRules(){const id=profileId.value,version=viewVersion,ticket=++loadVersion;if(!id){loading.value=false;return;}loading.value=true;error.value='';try{const result=await getPersonalThresholds(id);if(id===profileId.value&&version===viewVersion&&ticket===loadVersion)data.value=result}catch(e){if(id===profileId.value&&version===viewVersion&&ticket===loadVersion){data.value={};error.value=e.message}}finally{if(ticket===loadVersion)loading.value=false}}
function open(row,isRestore){if(data.value.profile_id!==profileId.value)return ElMessage.warning('请等待当前老人的阈值加载完成');formProfileId.value=profileId.value;form.value={...row,reason:''};restore.value=isRestore;dialog.value=true}
async function submit(){if(saving.value)return;const id=formProfileId.value,version=viewVersion;if(!id||id!==profileId.value||!dialog.value)return ElMessage.warning('老人已切换，请重新打开阈值申请');if(!form.value.reason.trim())return ElMessage.warning('请填写调整依据');saving.value=true;try{const body={indicator:form.value.indicator,reason:form.value.reason,restore_default:restore.value};if(!restore.value)for(let n=0;n<4;n++)body['level'+n+'_range']=form.value['level'+n+'_range'];await proposePersonalThreshold(id,body);if(id!==profileId.value||version!==viewVersion)return;dialog.value=false;await loadRules();ElMessage.success('申请已提交，审核前继续使用当前阈值')}catch(e){if(id===profileId.value&&version===viewVersion)ElMessage.error(e.message)}finally{saving.value=false}}
onMounted(async()=>{loading.value=true;try{profiles.value=await listProfiles();const requested=Number(route.query.profile_id || route.params.id);profileId.value=profiles.value.find(p=>p.profile_id===requested)?.profile_id || profiles.value[0]?.profile_id;await loadRules()}catch(e){error.value=e.message}finally{loading.value=false}})
</script>
